import java.time.*;import java.util.*;class TaskBinding{static LocalDate firstDay(){return LocalDate.of(2026,10,1);}static Object create(){ScheduleAPI s=new Schedule();prepare(s);return s;}static void prepare(ScheduleAPI s){s.createSchedule();s.createSubject("s1","Math");s.createSubject("s2","History");s.createTeacher("t1","Teacher One");s.createTeacher("t2","Teacher Two");s.createGroup("g1","9A");s.createGroup("g2","9B");s.addLesson(lesson("l1",1,9,"s1","t1","g1","A",Schedule.Kind.THEORY,""));s.addLesson(lesson("l2",1,10,"s2","t2","g1","B",Schedule.Kind.THEORY,""));s.addLesson(lesson("l3",2,9,"s1","t1","g2","A",Schedule.Kind.THEORY,""));s.addLesson(lesson("l4",2,10,"s2","t2","g2","B",Schedule.Kind.THEORY,""));}static Schedule.Lesson lesson(String id,int day,int hour,String subject,String teacher,String group,String room,Schedule.Kind kind,String car){return new Schedule.Lesson(id,LocalDate.of(2026,10,day),LocalTime.of(hour,0),subject,teacher,group,room,kind,car);}static Set<String>teacherIds(Object x,String id){Set<String>ids=new HashSet<>();for(var l:((ScheduleAPI)x).forTeacher(id))ids.add(l.id());return ids;}static Set<String>groupIds(Object x,String id){Set<String>ids=new HashSet<>();for(var l:((ScheduleAPI)x).forGroup(id))ids.add(l.id());return ids;}static int teacherCount(Object x,String id){return ((ScheduleAPI)x).countTeacher(id);}static int groupCount(Object x,String id){return ((ScheduleAPI)x).countGroup(id);}static Map<String,String>subjects(Object x){Map<String,String>out=new HashMap<>();for(var s:((ScheduleAPI)x).subjects())out.put(s.id(),s.name());return out;}static Map<String,String>teachers(Object x){Map<String,String>out=new HashMap<>();for(var t:((ScheduleAPI)x).teachers())out.put(t.id(),t.name());return out;}static void rename(Object x){ScheduleAPI s=(ScheduleAPI)x;s.changeSubject("s1","Algebra");s.changeTeacher("t1","Revised");}static void room(Object x){((ScheduleAPI)x).changeRoom("l1","C");}static String roomOfFirst(Object x){return ((ScheduleAPI)x).forTeacher("t1").stream().filter(l->l.id().equals("l1")).findFirst().orElseThrow().room();}static void cancel(Object x){((ScheduleAPI)x).cancelLesson("l2");}static void extra(Object x){((ScheduleAPI)x).addExtraLesson(lesson("l5",1,11,"s1","t1","g1","D",Schedule.Kind.THEORY,""));}static void holiday(Object x){((ScheduleAPI)x).addHoliday(firstDay());}static boolean holidayExcluded(Object x){for(String id:new String[]{"t1","t2"})for(var l:((ScheduleAPI)x).forTeacher(id))if(l.date().equals(firstDay()))return false;return true;}static void deleteSubject(Object x){((ScheduleAPI)x).deleteSubject("s1");}static void deleteTeacher(Object x){((ScheduleAPI)x).deleteTeacher("t1");}static String deletionPolicy(){return "cascade";}static void deleteSchedule(Object x){((ScheduleAPI)x).deleteSchedule();}static void recreate(Object x){((ScheduleAPI)x).createSchedule();}static Object school(){SchoolSchedule s=new SchoolSchedule(2);prepare(s);return s;}static int schoolLimit(){return 2;}static int classSize(Object x){return ((SchoolAPI)x).forClass("g1").size();}static boolean schoolValid(Object x){return ((SchoolAPI)x).withinDailyLimit("g1",firstDay());}static Object driving(){DrivingSchedule s=new DrivingSchedule();prepare(s);s.registerCar("c1");s.addExtraLesson(lesson("p1",1,11,"s1","t1","g1","Road",Schedule.Kind.PRACTICE,"c1"));return s;}static boolean car(Object x,String id){return ((DrivingAPI)x).carAvailable(id);}static int theory(Object x){return ((DrivingAPI)x).theory("g1").size();}static int practice(Object x){return ((DrivingAPI)x).practice("g1").size();}}
